    "r_fix_b": {"media":{"kind":"video","file":"https://p5-ad.adkwai.com/udata/pkg/KS-GAME/AIGC-SoGame/ks667658648250668260/n5_fix_b.mp4","duration":10,"label":"点石成屋","poster":"images/lastframes/n5_fix_b.jpg"},"char":"aotian","speaker":"你（低声）","text":"点石成屋。","unlockSkill":"skill_house","next":"r_fix_b_grand","ep":"EP05","scene":"house"},
    "r_fix_b_grand": {"media":{"kind":"video","file":"https://p5-ad.adkwai.com/udata/pkg/KS-GAME/AIGC-SoGame/ks667658648250668260/n5_fix_b_grand.mp4","duration":10,"label":"土屋化豪宅","poster":"images/lastframes/n5_fix_b_grand.jpg"},"char":"wanerh","speaker":"沈婉儿（惊喜）","text":"傲天，你太牛了吧！房子直接变成大豪宅了！","next":"e5s4","ep":"EP05","scene":"house"},
    "r_fix_c": {"media":{"kind":"video","file":"https://p5-ad.adkwai.com/udata/pkg/KS-GAME/AIGC-SoGame/ks667658648250668260/n5_fix_c.mp4","duration":10,"label":"湿被子里挨到天亮","poster":"images/lastframes/n5_fix_c.jpg"},"char":"wanerh","speaker":"沈婉儿（发抖）","text":"有你在，这屋漏就漏吧。","next":"e5_bridge","ep":"EP05","scene":"house"},
    "e5_bridge": {"media":{"kind":"video","file":"https://p5-ad.adkwai.com/udata/pkg/KS-GAME/AIGC-SoGame/ks667658648250668260/n5_bridge.mp4","duration":10,"label":"天亮·雨停·屋还得修","poster":"images/lastframes/n5_bridge.jpg"},"char":"narrator","speaker":"旁白","text":"天亮雨停了。可这屋，还是得修。","next":"f5_fix2","ep":"EP05","scene":"house"},
    "f5_fix2": {"type":"choice","title":"天亮了。这屋还是得修——现在再想想？","options":[{"text":"还是爬房顶","icon":"fight","stat":{"wei":5,"qing":-5},"next":"BE_ROOF","id":"f5_fix2_opt_0","roastKey":"roast_roof_fall2","roast":"天亮了你还是不信邪，踩着湿瓦往上爬。一脚踏空，七尺高的房檐——这回婉儿连尖叫都没来得及。"},{"text":"翻技能库·点石成屋","icon":"say","stat":{"liang":15,"wei":5},"next":"r_fix_b","id":"f5_fix2_opt_1","ad":true,"adUnitId":"2300058116_01"}],"ep":"EP05","scene":"house"},
